-- 2259 🏋️ Exercises from the book "pep-guardiola-attacking-tactics-tactical-analysis-and-sessions-from-manchester-c" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'pep-guardiola-attacking-tactics-tactical-analysis-and-sessions-from-manchester-c');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('Beat forward press via link player pattern', 'combination', 'unopposed', 'in_possession', 26, 27, 'Session 1: Practice 1', 'Guardiola (Man City)', 'Escape the opposing forwards'' press on the centre backs and move the ball to the weak side, finishing with a cross and shot.', 'Attacking half with red mannequins set as a 4-4-2 block; blue centre backs, full backs, defensive midfielder, attacking midfielders, wingers and forward start on blue cones; GK in goal and two coaches with balls by the end line.', 'One centre back passes across to the other, who dribbles at the nearest mannequin and plays into the attacking midfielder dropping back as a link player (or via the full back); the link player sets the defensive midfielder, who switches to the weak-side full back, on to the winger, who dribbles and crosses for the forward. After the shot the attacking midfielder finishes a second ball fed by the coach from the end line; repeat on the other side.', NULL, 'Scenario B: the receiving centre back plays straight into the defensive midfielder and the forward drops back as the link player to set the weak-side full back, who finds the winger.', 'Accurate, high-speed passing; well-timed drops of the link player (attacking midfielder or forward); accurate crossing and finishing.', '10 outfield + GK + 2 coaches (2 per advanced position to keep tempo)', 11, 16, 'Attacking half', NULL, NULL, NULL, true, true, true, NULL, 10),
  ('Beat the press and switch: 2-zone game', 'conditioned_game', 'opposed', 'in_possession', 28, 28, 'Session 1: Practice 2', 'Guardiola (Man City)', 'Play through the forwards'' press and switch the ball to the weak side to exploit the free numbers there.', 'Large area split lengthways into two halves; two full goals with GKs at the far end and two mini goals on the near line with coaches holding balls; blues in 4-3-3 shape v reds in 4-4-2 shape.', 'A coach passes to a blue centre back; the nearest red forward presses at once to force play wide and build a 6v5 on that side. Blues either score on the strong side despite being outnumbered or, preferably, use a dropping attacking midfielder as link player to switch into the other half and score there with the overload.', 'If reds win the ball they must score in either mini goal within 8-12 seconds.', NULL, 'Timing of the attacking midfielder''s drop to become the link for the switch.', '10v10 + 2 GKs', 22, 22, 'Attacking half / 3/4 pitch split into 2 vertical halves', NULL, NULL, NULL, true, true, true, NULL, 20),
  ('Inverted full back rotation passing', 'passing_unopposed', 'unopposed', 'in_possession', 36, 36, 'Session 2: Practice 1', 'Guardiola (Man City)', 'Rehearse the rotation of inverted full back, attacking midfielder and winger triggered by the midfielder dropping.', 'Two groups of 5 (centre back, inverted full back, defensive midfielder, attacking midfielder, winger) on blue cones, one on each side of the halfway area, with red mannequins as opponents; both groups work at once.', 'Centre back plays a one-two with the inverted full back; the attacking midfielder drops, which triggers the full back to go wide and the winger to tuck in. Centre back passes to the defensive midfielder, who plays first time to the dropped attacking midfielder, who finds the winger; winger plays first time back to the defensive midfielder, who returns it to the centre back, and the three rotators carry on from their new spots.', '1-2 touches.', NULL, 'Attacking midfielder triggers the rotation; well-timed synchronised movement; high-speed passing.', '2 groups of 5', 10, 10, NULL, NULL, NULL, NULL, false, false, false, NULL, 30),
  ('Inverted full back rotations: twin 5v4 games', 'phase_of_play', 'overload', 'in_possession', 37, 37, 'Session 2: Practice 2', 'Guardiola (Man City)', 'Attack after the full back / midfielder / winger rotation in a wide area to unbalance the defence and score.', 'Area split lengthways into two halves, each with a full goal and GK at the top and a mini goal at the bottom; two coaches with balls; a blue centre back on each side and two defensive midfielders in the middle.', 'Both halves play at the same time. The centre back passes to a defensive midfielder, who then enters to make 5v4; the attacking midfielder dropping back triggers the rotation of full back, midfielder and winger, and the blues try to score.', 'Blues must score within a set time (about 15 seconds) or the coach feeds a red who tries to score in the mini goal quickly; if reds win the ball they must score in the mini goal within 8-12 seconds.', NULL, 'High tempo; perfectly synchronised rotation; quick finishing (2 touch max).', '5v4 + GK in each half (2 games)', 18, 22, 'Attacking half split into 2 vertical halves', NULL, NULL, NULL, true, true, true, NULL, 40),
  ('Wide 2v1: receive and turn outside', 'combination', 'unopposed', 'in_possession', 49, 49, 'Session 3: Practice 1', 'Guardiola (Man City)', 'Exploit a 2v1 wide by the attacking midfielder receiving in the wide zone and turning outside.', 'Attacking half with 8 red mannequins in formation and 3 yellow mannequins as the back line for crosses; yellow zones out wide in front of the box; blues on cones (centre back, full back, defensive midfielder, attacking midfielders, wingers, forward) and a GK.', 'Centre back starts the pattern to the full back; the defensive midfielder offers inside while the attacking midfielder steps into the yellow zone and receives, turns outside and either crosses early or slips the winger to dribble on and cross. The forward, other attacking midfielder and far winger time runs into the gaps between the yellow mannequins to finish; repeat on the right.', '1-2 touch passing.', NULL, 'Quality high-speed passing; early or high crosses and accurate finishing; synchronised runs.', '9 + GK (2 per advanced position)', 10, 15, 'Attacking half', NULL, NULL, NULL, true, true, true, NULL, 50),
  ('Wide 2v1: receive and turn inside', 'combination', 'unopposed', 'in_possession', 50, 50, 'Session 3: Practice 2', 'Guardiola (Man City)', 'Exploit a 2v1 wide by moving the ball through the defensive midfielder so the attacking midfielder can receive and turn inside.', 'Same set-up as Practice 1: mannequin block, yellow wide zones, blues on cones, GK in goal.', 'Full back passes inside to the defensive midfielder as link player, who finds the attacking midfielder in the yellow zone; he turns inside and dribbles at the mannequin centre back while the forward, other attacking midfielder and winger make runs in behind for the final pass and finish. Repeat on the right.', '1-2 touch passing.', NULL, 'Quality high-speed passing; low crosses and accurate finishing; synchronised movement.', '9 + GK (2 per advanced position)', 10, 15, 'Attacking half', NULL, NULL, NULL, true, true, true, NULL, 60),
  ('Free the winger when the full back presses', 'combination', 'passive', 'in_possession', 51, 52, 'Session 3: Practice 3', 'Guardiola (Man City)', 'Get the ball to the free winger when the opposing full back steps up on the attacking midfielder.', 'Practice 1-2 set-up plus two red full backs placed inside the wide yellow zones, coached to press the attacking midfielder when he receives.', 'Defensive midfielder plays to the attacking midfielder after an inside pass from the full back; the red full back steps up. Blues find the winger by one of three routes: back to the defensive midfielder for an aerial ball, back to the full back for a pass down the line, or inside to the forward who plays wide. Advanced players attack the box for the cross; repeat on the right.', '1-2 touch passing.', 'Scenario B: the full back passes straight to the attacking midfielder (no inside pass to the defensive midfielder), so the inside-to-forward option is removed.', 'Quality high-speed passing; low crosses and accurate finishing; synchronised movement.', '9 + GK v 2 defenders', 12, 17, 'Attacking half', NULL, NULL, NULL, true, true, true, NULL, 70),
  ('Read the full back to exploit wide 2v1', 'phase_of_play', 'opposed', 'in_possession', 53, 54, 'Session 3: Practice 4', 'Guardiola (Man City)', 'Choose the right way to use the wide overload depending on whether the opposing full back holds or steps up.', 'Same pattern start, now against 4 live red defenders (full backs inside the yellow zones plus 2 centre backs) and a GK, with mannequins in midfield.', 'The red full back decides whether to press the attacking midfielder or stay with the winger. If he stays, the midfielder receives in the yellow zone, turns and plays a final pass in behind or dribbles inside; if he presses, the ball goes to the free winger through one of the three combinations, who crosses for the runners.', '1-2 touch passing; red defenders defend normally.', 'Scenario A: full back stays back - midfielder turns and plays in the forward. Scenario B: full back presses - free the winger.', 'Read the full back''s reaction; quality fast passing; low crossing and finishing; synchronised movement.', '9 + GK v 4 defenders + GK', 15, 20, 'Attacking half', NULL, NULL, NULL, true, true, true, NULL, 80),
  ('Wide 2v1 overload 9v8 game', 'small_sided_game', 'overload', 'in_possession', 55, 55, 'Session 3: Practice 5', 'Guardiola (Man City)', 'Exploit the wide overload in a game, choosing the option from the opposing full back''s reaction.', 'Attacking half with a full goal and GK; two mini goals on the halfway line; 9 blues v 8 reds + GK.', 'Play starts with the blue centre back passing from the end line. Blues attack and try to create and use 2v1s out wide, with the attacking midfielder reading the full back to pick the option.', 'Any blue goal 1 point, goal after exploiting a wide 2v1 = 2 points. Reds winning the ball score in either mini goal within 10-12 seconds for 2 points.', NULL, 'Attacking midfielder reads the opposing full back; synchronised movement.', '9v8 + GK', 18, 18, 'Attacking half', NULL, NULL, NULL, true, true, true, NULL, 90),
  ('Wide 2v1 overload 11v11 game', 'conditioned_game', 'opposed', 'in_possession', 56, 56, 'Session 3: Practice 6', 'Guardiola (Man City)', 'Apply wide 2v1 overloads in a full conditioned game.', 'Two teams 11v11 on a pitch (shown over roughly two-thirds length) with full goals and GKs.', 'Play starts from the blue goalkeeper; blues build up and look to create and exploit 2v1s out wide using the combinations from the session.', 'Blue goal 1 point, after exploiting a wide 2v1 = 2 points. Reds scoring within 12-15 seconds of winning the ball get 2 points.', NULL, 'Attacking midfielder reads the opposing full back; synchronised movement.', '11v11', 22, 22, NULL, NULL, NULL, NULL, true, true, true, NULL, 100),
  ('Blocked overload: options vs 4 defenders', 'passing_opposed', 'passive', 'in_possession', 61, 62, 'Session 4: Practice 1', 'Guardiola (Man City)', 'Read whether one or both opposing central midfielders shift across, then pick the right way to break through when the 2v1 out wide is blocked.', 'Half pitch with goal and GK; two central white zones each holding a red central midfielder, two wide yellow zones holding red full backs; blues start on cones in a 2-3-2-3 shape, plus mannequins.', 'Blues play a set pattern from the centre back to the full back. If one red midfielder shifts into the yellow zone, the forward drops into the widened lane, receives in the white zone, turns and plays the winger in behind. If both shift, the full back goes inside to the defensive midfielder, who finds the weak-side attacking midfielder (or switches to the winger) to turn and play in behind.', 'Restart with the pattern on the right side; 2 players per advanced position to keep the tempo up.', 'Scenario A: one red central midfielder shifts across; Scenario B: both shift across so play goes to the weak side.', 'Forward and full back read how many midfielders shift; 1-2 touch high speed passing; low crosses and finishing; synchronised movement.', '9 blues v 4 reds + GK', 14, 19, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 110),
  ('Blocked overload: options vs 6 defenders', 'passing_opposed', 'opposed', 'in_possession', 63, 65, 'Session 4: Practice 2', 'Guardiola (Man City)', 'Add two live centre backs so the blues must read midfielders and centre backs before choosing where to attack.', 'Same zones as Practice 1 with two active red centre backs added; blues start on cones, GK in goal.', 'After the ball reaches the full back, the forward drops into the white zone. If the centre back stays, the forward turns and plays the winger in behind. If the centre back presses him, the forward sets back to the defensive midfielder, who plays an aerial ball in behind for the attacking midfielder to score or square. If the passing lane to the forward is shut, the full back goes inside to the defensive midfielder to switch to the weak side.', 'Restart with the pattern on the right side.', 'Scenario A: centre back holds, forward turns. Scenario B: centre back presses, lay-off and aerial pass in behind. Scenario C: lane to forward blocked, switch to weak-side attacking midfielder or winger.', 'Forward and full back read central midfielders and centre backs; 1-2 touch quality passing; low crosses; synchronised movement.', '9 blues v 6 reds + GK', 16, 21, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 120),
  ('Blocked overload dynamic 10v10 game', 'phase_of_play', 'opposed', 'in_possession', 66, 66, 'Session 4: Practice 3', 'Guardiola (Man City)', 'Apply the blocked-overload solutions in a live 10v10 with a counter for the defenders.', 'About two thirds of the pitch: big goal with GK for the blues to attack, two mini goals on the halfway line for the reds; white and yellow zones marked.', 'Blues build from the back and attack; e.g. when a red midfielder shifts wide the forward drops into the widened lane, receives in the white zone, turns and plays the winger in. Reds win the ball and counter to the mini goals.', 'Blues: any goal 1 point, 2 points after exploiting a 2v1 out wide or using one of the blocked-overload options. Reds: 2 points for scoring in a mini goal within 8-12 seconds of winning it.', NULL, 'Read the central midfielders and centre backs; 1-2 touch passing; low crosses; synchronised movement.', '10v10 + GK', 21, 21, 'Two thirds of a pitch', NULL, NULL, NULL, true, true, true, NULL, 130),
  ('Blocked overload 11v11 conditioned game', 'conditioned_game', 'opposed', 'in_possession', 67, 67, 'Session 4: Practice 4', 'Guardiola (Man City)', 'Use the blocked-overload attacking options in a full-sized game.', 'Full pitch, 11v11, play starts from the blue goalkeeper.', 'Normal game. Example: both red central midfielders shift across so the lane to the forward closes; the left back plays inside to the defensive midfielder, who finds the free weak-side attacking midfielder.', 'Blues 1 point for any goal, 2 points after a 2v1 out wide or a blocked-overload option. Reds 2 points for scoring within 12-15 seconds of winning the ball.', NULL, NULL, '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 140),
  ('Receive behind full back or inside pass', 'passing_opposed', 'opposed', 'in_possession', 73, 74, 'Session 5: Practice 1', 'Guardiola (Man City)', 'Read the opposing defenders to either pass in behind the full back or play inside between the lines to the forward.', 'Half pitch with goal and GK; blues start on cones against a red back 4, mannequins in midfield; two wide yellow zones for the wingers.', 'Set pattern to the full back; the attacking midfielder runs in behind the opposing right back while the full back finds the winger in the yellow zone. If the centre back does not track the run, the winger plays the attacking midfielder in behind to cross, pass or shoot. If the centre back tracks, the forward shifts across to take an inside pass free of marking and picks the best option in behind.', 'Opposing full back lets the winger receive then presses him. Restart with the pattern on the right side.', 'Scenario A: centre back holds position. Scenario B: centre back follows the attacking midfielder''s run.', 'Winger and forward read the centre back; 1-2 touch passing; good crosses and timed final balls; winger and attacking midfielder in sync.', '9 blues v 4 reds + GK', 14, 14, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 150),
  ('Behind full back 9v8 small sided game', 'small_sided_game', 'opposed', 'in_possession', 75, 75, 'Session 5: Practice 2', 'Guardiola (Man City)', 'Read the defenders and either get in behind the full back or play inside to the forward, in a live game.', 'Large area towards one goal with GK; two mini goals on the end line for the reds; blues start with the centre back passing from the end line.', 'Blues move the ball wide and look for the run in behind or the inside pass to the forward between the lines. E.g. centre back tracks the attacking midfielder, so the forward drifts across and receives the inside pass from the winger. Reds counter to the mini goals.', 'Blues 1 point any goal, 2 points if the goal follows the ball reaching a winger and a pass in behind the full back or into the forward between the lines. Reds 2 points within 10-12 seconds of winning it.', NULL, 'Winger and forward read the centre back; synchronised winger and attacking midfielder runs.', '9v8 + GK', 18, 18, NULL, NULL, NULL, NULL, true, true, true, NULL, 160),
  ('Behind full back 11v11 conditioned game', 'conditioned_game', 'opposed', 'in_possession', 76, 76, 'Session 5: Practice 3', 'Guardiola (Man City)', 'Exploit space behind the full back or an inside pass to the forward in a full game.', 'Full pitch 11v11, starting from the blue goalkeeper.', 'Normal game; e.g. when the opposing full back sits wide the winger drops to pull him, then spins and takes a through ball from the full back in behind.', 'Blues 1 point any goal, 2 points after going wide to a winger and passing behind the full back or into the forward between the lines. Reds 2 points within 12-15 seconds of a turnover.', NULL, NULL, '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 170),
  ('Wide combinations past mannequins', 'combination', 'unopposed', 'in_possession', 84, 85, 'Session 6: Practice 1', 'Guardiola (Man City)', 'Wide combination play (one-two or give-and-go) to break through the defence.', '35 x 45 yard area with a goal and GK, mannequins as defenders; starts with the full back, two players in each winger position.', 'Full back to winger; winger dribbles at the mannequin or inside depending on the attacking midfielder. One-two: attacking midfielder checks away and shows in front of the mannequin, winger passes and runs in behind for the return. Give-and-go: attacking midfielder runs forward to drag his marker, defensive midfielder steps into the space, winger passes back to him and curls a run to take the aerial pass in behind and cross.', 'Restart with the pattern on the right side.', 'Scenario A: one-two with the attacking midfielder. Scenario B: give-and-go with the defensive midfielder.', '1-2 touch high speed passing; well-timed winger runs; low crosses; synchronised movement.', '8 players + GK', 9, 12, '35 x 45 yards', 41.1, 32.0, NULL, true, true, true, NULL, 180),
  ('Wide combinations functional practice', 'passing_opposed', 'passive', 'in_possession', 86, 87, 'Session 6: Practice 2', 'Guardiola (Man City)', 'Choose between a one-two and a give-and-go out wide based on the attacking midfielder''s movement.', 'Half pitch with goal and GK; blues start on cones vs two red central midfielders and two red full backs, with mannequins; wide zones for wingers.', 'Set pattern to the winger, who reads the attacking midfielder: if he checks away and shows, play a one-two and run behind the full back; if he runs forward to drag his marker, pass back diagonally to the defensive midfielder and curl a run for the aerial ball in behind, then cross.', 'Red full backs are semi-active and do not tackle; red midfielders just follow the attacking midfielders. Restart on the right; 2 players in each winger spot.', 'Scenario A: one-two with the attacking midfielder. Scenario B: give-and-go with the defensive midfielder.', 'Dribble at the full back before a one-two, dribble inside before a give-and-go; 1-2 touch passing; timed runs; low crosses.', '10 blues v 4 reds + GK', 15, 17, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 190),
  ('Wide combinations 8v7 game with end zone', 'small_sided_game', 'opposed', 'in_possession', 88, 89, 'Session 6: Practice 3', 'Guardiola (Man City)', 'Use one-two and give-and-go combinations out wide in a live game.', '35 x 45 yard area, 10 yard end zone in front of the goal with GK, two wide yellow zones for blue wingers and red full backs only; two mini goals for the reds at the other end; coaches with spare balls.', 'Blues work the ball to a winger in a yellow zone, who plays a one-two with the attacking midfielder or a give-and-go with the defensive midfielder, depending on the attacking midfielder''s movement, then finishes or crosses. Reds win it and attack the mini goals.', 'No reds in the end zone; red full backs may not stop wingers receiving in the yellow zones; once reds win the ball they move freely; offside applies. A failed blue combination means the coach feeds a new ball to the reds.', 'Scenario A: one-two. Scenario B: give-and-go.', 'Dribble at the full back before a one-two, inside before a give-and-go.', '8v7 + GK', 16, 16, '35 x 45 yards', 41.1, 32.0, NULL, true, true, true, NULL, 200),
  ('Wide combinations 10v10 conditioned game', 'phase_of_play', 'opposed', 'in_possession', 90, 90, 'Session 6: Practice 4', 'Guardiola (Man City)', 'Wide combination play to break through in a bigger game.', 'About two thirds of the pitch, big goal with GK, two mini goals for the reds on the halfway line, end zone and wide zones marked; start with the centre back from the end line.', 'Blues build and score, looking for a one-two or give-and-go out wide; reds counter to the mini goals.', 'Blues 1 point any goal, 2 after a successful one-two or give-and-go. Reds 2 points within 10-12 seconds. A red may only enter the end zone after a blue receives in it.', '11v11 on two thirds of the pitch.', 'Dribble at the full back before the one-two, inside before the give-and-go; communication between attacking midfielder and winger.', '10v10 + GK', 21, 22, 'Two thirds of a pitch', NULL, NULL, NULL, true, true, true, NULL, 210),
  ('Stretch and switch long-pass circuit', 'passing_unopposed', 'unopposed', 'in_possession', 97, 98, 'Session 7: Practice 1', 'Guardiola (Man City)', 'Switch play with long passes into the space created after stretching the defence.', '50 x 70 yard zone with mannequins; centre back in a 7 x 3 zone, defensive midfielder in a 15 x 5 zone, wingers in 3 x 3 wide zones, a large receiving zone and mini goal in the far half.', 'Centre back to winger, who passes to the defensive midfielder directly or via the full back. The receiver plays a long pass either to the attacking midfielder in the centre or wider to the far winger, who receives in the large zone and scores in the mini goal.', 'Receivers must control inside the large zone. Restart on the right; 2 players per advanced position.', 'Scenario A vs 4-4-2: defensive midfielder plays the long pass. Scenario B vs 4-2-3-1: weak-side full back shifts across and plays it.', 'Receivers time their runs; long passes accurate into the free space.', '8 players', 8, 12, '50 x 70 yards', 64.0, 45.7, NULL, true, false, true, NULL, 220),
  ('Stretch and switch pattern of play', 'combination', 'unopposed', 'in_possession', 99, 100, 'Session 7: Practice 2', 'Guardiola (Man City)', 'Stretch the defence, switch play, receive in space and score.', 'Half pitch with goal and GK, mannequins as defenders; blues on white cones; marked central white and wide yellow receiving zones.', 'Set pattern from the centre back to the winger, who passes to the defensive midfielder (central zone) or via the full back. A long pass goes to the attacking midfielder in the central white zone or the winger in the wide yellow zone, who shoots or crosses.', 'Restart on the right; 2 players per advanced position.', 'Scenario A vs 4-4-2: defensive midfielder switches. Scenario B vs 4-2-3-1: weak-side full back receives and switches.', 'Timed runs; accurate long passes; low crosses and finishing; synchronised movement.', '9 players + GK', 10, 14, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 230),
  ('Stretch and switch vs back four', 'passing_opposed', 'opposed', 'in_possession', 101, 102, 'Session 7: Practice 3', 'Guardiola (Man City)', 'Read how the back four reacts and direct the switch into the space created.', 'Half pitch with goal and GK, mannequins in midfield, red back 4; blues on white cones; central and wide zones.', 'Ball reaches the strong-side winger, the red full back closes him, the near attacking midfielder runs diagonally behind and is tracked by the centre back. Blues quickly switch via the defensive midfielder (or the full back) while forward, far attacking midfielder and winger run into their zones; long pass to wherever space opened, then shot or cross.', 'Restart on the right side.', 'Scenario A vs 4-4-2: far attacking midfielder drags the full back, winger gets the long pass wide. Scenario B vs 4-2-3-1: full back switches; if the red full back does not shift, attacking midfielder takes it centrally.', 'Where has the space opened; quality long passing; low crosses and finishing.', '9 blues v 4 reds + GK', 14, 14, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 240),
  ('Stretch and switch zonal game', 'phase_of_play', 'opposed', 'in_possession', 103, 104, 'Session 7: Practice 4', 'Guardiola (Man City)', 'Switch play under pressure from red midfielders and forwards.', 'Two thirds of the pitch, big goal with GK, mannequins as back line, two mini goals for reds; wide blue zones for wingers and a central white zone the weak-side red wide midfielder cannot enter; start with the centre back, 5v4 in the lower part.', 'Blues either switch to the weak side or pass into the forward; the threat of the forward pass drops a red midfielder and frees the defensive midfielder to switch. Receiver shoots or crosses. Reds counter to the mini goals.', 'If reds win it or a switch is inaccurate (not into zones), the coach feeds a new ball to the reds to score in the mini goals.', 'Scenario B vs 4-2-3-1: if the No.10 shuts out the defensive midfielder, the weak-side full back switches. Then add 4 red defenders for 10v10 (+GK).', 'Where is the space; 1-2 touch passing; accurate long passing; low crosses; synchronised movement.', '10 blues v 6 reds + GK (prog 10v10 + GK)', 17, 21, 'Two thirds of a pitch', NULL, NULL, NULL, true, true, true, NULL, 250),
  ('Stretch and switch 11v11 conditioned game', 'conditioned_game', 'opposed', 'in_possession', 105, 105, 'Session 7: Practice 5', 'Guardiola (Man City)', 'Stretch the defence, switch play, receive in space and score in a full game.', 'Full pitch 11v11 starting from the blue goalkeeper.', 'Normal game; blues look to stretch then switch with a long pass into the space.', 'Blues 1 point any goal, 2 after stretching and switching. Reds 2 points within 12-15 seconds.', 'Play against a 4-2-3-1 so the full back receives and plays the long pass.', 'Winger reads whether to go direct to the defensive midfielder or via the full back; where to aim the long pass; 1-2 touch passing; quality long passing.', '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 260),
  ('Between-the-lines receiving passing practice', 'passing_opposed', 'passive', 'in_possession', 111, 114, 'Session 8: Practice 1', 'Guardiola (Man City)', 'Attacking midfielders receive between the lines and read the opposing full back to turn or lay off.', '35 x 45 yard area with goal and GK, mannequins; a 20 x 5 white central zone for the two attacking midfielders and two 8 x 5 yellow wide zones for the wingers and red full backs.', 'Blue back 4 circulates; when the defensive midfielder receives on the half-turn the attacking midfielders move into lanes. He passes to one: if the red full back stays in the yellow zone, the attacking midfielder turns and plays a key pass. If the full back steps in to stop the turn, he lays off to the defensive midfielder, who plays an aerial ball in behind for the winger to shoot or cross.', NULL, 'Scenarios A/B: strong- or weak-side attacking midfielder receives unmarked. Scenarios C/D: full back presses the strong- or weak-side attacking midfielder.', 'Read the full back to turn or lay off; open body shape and quick turn; 1-2 touch passing; low crosses; timed runs in behind, onside.', '10 blues v 2 reds + GK', 13, 13, '35 x 45 yards', 41.1, 32.0, NULL, true, true, true, NULL, 270),
  ('Between-the-lines functional practice vs back four', 'passing_opposed', 'opposed', 'in_possession', 115, 116, 'Session 8: Practice 2', 'Guardiola (Man City)', 'Attacking options after the attacking midfielder receives between the lines against a full back four.', 'Half pitch with goal and GK vs red back 4, mannequins in midfield; 30 x 5 yard white central zone, two 12 x 8 yellow wide zones.', 'Back 4 circulates; defensive midfielder receives on the half-turn and finds an attacking midfielder. Full back stays: turn and key pass. Full back steps in: lay off to the defensive midfielder for an aerial pass in behind to the winger, who crosses.', NULL, 'Scenario A: attacking midfielder unmarked. Scenario B: full back prevents the turn.', 'Read the full back to turn or lay off; open body shape; 1-2 touch passing; low crosses; timed runs in behind.', '10 blues v 4 reds + GK', 15, 15, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 280),
  ('Between-the-lines 10v10 conditioned game', 'phase_of_play', 'opposed', 'in_possession', 117, 117, 'Session 8: Practice 3', 'Guardiola (Man City)', 'Attacking options for the attacking midfielder after receiving between the lines, in a live game.', 'Two thirds of the pitch, big goal with GK, two mini goals for reds; central white zone and wide zones marked; start with the centre back from the end line.', 'Blues build up and score, aiming to get the defensive midfielder''s pass into an attacking midfielder between the lines; reds counter to the mini goals.', 'Blues 1 point any goal, 2 after the defensive midfielder finds an attacking midfielder between the lines. Reds 2 points within 10-12 seconds. Only red full backs may enter the white zone to stop the attacking midfielders turning.', 'Zones are only a reading aid and can be removed.', NULL, '10v10 + GK', 21, 21, 'Two thirds of a pitch', NULL, NULL, NULL, true, true, true, NULL, 290),
  ('Exploit pushed-out centre back, unopposed', 'combination', 'unopposed', 'in_possession', 122, 123, 'Session 9: Practice 1', 'Guardiola (Man City)', 'Find and use the space left when an opposing centre back steps out to press an attacking midfielder.', '35 x 45 yard area with a goal and GK; a 12 x 5 yd white central zone flanked by two 4 x 5 yd yellow wide zones for the two attacking midfielders, mannequins as defenders; blue back 4 plus a holding mid and a forward start the pattern from the centre back.', 'Back 4 circulate; when the 6 gets the ball between the lines on the half-turn, both 8s move into passing lanes in a wide or central zone and one receives. Scenario A (8 wide, imagined CB presses diagonally): 8 plays a vertical ball in behind for the 9 to score. Scenario B (8 central, CB presses straight on): 8 plays a 1-2 with the 9 and runs past the mannequin to finish.', 'Receiving attacking midfielder limited to 2 touches.', 'Scenario A and B alternate depending on where the 8 receives.', 'Read the situation (where the 8 receives decides the 9''s move); open body shape and quick turn; 1-2 touch passing at speed; clean finishing; well-timed runs.', '7 attackers + GK', 8, 8, '35 x 45 yards', 41.1, 32.0, NULL, true, true, true, NULL, 300),
  ('Exploit pushed-out centre back vs 2 CBs', 'phase_of_play', 'opposed', 'in_possession', 124, 125, 'Session 9: Practice 2', 'Guardiola (Man City)', 'Read which red centre back steps out to press and punish the gap he leaves behind.', 'Same zoned area and pattern as Practice 1, now with two live red centre backs in front of the GK.', 'Back 4 pass, 6 receives, 8s show in the central or wide zones; the nearest red CB steps up to close the receiving 8. Wide 8 either slips the 9 in behind (vertical pass) or, if blocked, passes inside to the other 8 who feeds the 9. Central 8 plays a 1-2 with the 9 and runs into the space behind.', 'Attacking midfielder max 2 touches.', 'Scenario A (8 receives wide) and Scenario B (8 receives central).', 'Read the CB''s reaction; open body and quick turn; 1-2 touch passing; accurate finishing; timing of runs.', '7 attackers + GK v 2 CBs', 10, 10, '35 x 45 yards', 41.1, 32.0, NULL, true, true, true, NULL, 310),
  ('Pushed-out centre back functional vs back 4', 'phase_of_play', 'opposed', 'in_possession', 126, 127, 'Session 9: Practice 3', 'Guardiola (Man City)', 'Exploit the space behind a centre back who presses the attacking midfielder, against a full red back 4.', 'Final third of the pitch with GK; white central zone and yellow wide zones in front of the box, red mannequins in midfield; blue back 4, 6, two 8s and a 9 v red back 4.', 'Blues build from the back 4 to the 6; the 8s move into zones to receive. Red CB steps to the 8: wide 8 plays in behind to the 9 or inside to the other 8; central 8 plays a 1-2 with the 9 and runs into the space created.', 'Red full backs defend normally but may never enter the zones; attacking midfielder max 2 touches.', 'Scenario A (8 receives wide) and Scenario B (8 receives central).', 'Read the 8''s position and the CB''s reaction; open body shape and quick turn; 1-2 touch passing; finishing; timed runs.', '8 attackers v 4 defenders + GK', 13, 13, NULL, NULL, NULL, NULL, true, true, true, NULL, 320),
  ('Pushed-out centre back 10v10 game', 'conditioned_game', 'opposed', 'in_possession', 128, 128, 'Session 9: Practice 4', 'Guardiola (Man City)', 'Recognise and exploit a centre back stepping out to press in a game.', 'About two thirds of the pitch: big goal with GK at one end, two mini goals on the halfway end line; marked central and wide zones in front of the box; 10 v 10 (+GK), blues start with a centre back on the end line.', 'Blues attack the big goal; reds defend and, on winning the ball, counter to either mini goal.', 'Blue goal = 1 point, 2 points if scored after the 6 finds an 8 and they exploit the space left by the pressing CB. Reds score in a mini goal within 10-12 seconds = 2 points. Red full backs may not enter the zones; red CBs are coached to press the 8s in the zones. Zones are only a reading aid and can be removed.', '11v11 on 2/3 of the pitch, same aims, no zones.', NULL, '10v10 + GK', 21, 22, '2/3 of the pitch', NULL, NULL, NULL, true, true, true, NULL, 330),
  ('Forward drops to link, functional', 'phase_of_play', 'opposed', 'in_possession', 133, 134, 'Session 10: Practice 1', 'Guardiola (Man City)', 'Attack through the centre when the 8s are blocked by having the 9 drop off as a link player.', '35 x 45 yard area with GK; a low 20 x 5 yd and a high 12 x 5 yd white central zone (each split in half), two 12 x 20 yd yellow wide zones for the wingers; mannequins in midfield; blue back 4, 6, two 8s, 9 and two wingers v red back 4.', 'Back 4 pass; with the 8s'' lanes blocked, the 6 receives and the 9 drops into the low zone to set it. Scenario A: 9 lays to the strong-side 8, who dribbles into the space behind the CB to shoot or feeds the winger in the wide zone to cross. Scenario B: 9 lays to the weak-side 8 (2v2) who plays a first-time diagonal into the third-man run of the strong-side 8 behind the CB to finish.', NULL, 'Repeat with the 9 working the other side and the other red CB stepping in.', 'Read whether the ball goes to the strong-side or weak-side 8; open body and quick turn; 1-2 touch passing; finishing; timed runs.', '10 attackers v 4 defenders + GK', 15, 15, '35 x 45 yards', 41.1, 32.0, NULL, true, true, true, NULL, 340),
  ('Forward drops to link, 10v10 game', 'conditioned_game', 'opposed', 'in_possession', 135, 135, 'Session 10: Practice 2', 'Guardiola (Man City)', 'Use the dropping 9 and combinations to beat the pressing centre back in a game.', 'About two thirds of the pitch, big goal + GK v two mini goals; central zones marked; 10 v 10 (+GK), blues start from a centre back on the end line.', 'Blues attack the big goal looking for the 9 to drop, set an 8 and combine past the pressing CB (8 can dribble on, shoot or release a winger). Reds counter to a mini goal on regains.', 'Any blue goal 1 point, 2 if scored after passing to the dropping 9 and combining past the pressing CB. Reds 2 points in a mini goal within 10-12 seconds. Red full backs may not enter the central zones; red CBs press the 8s in their zones. Zones can be removed.', '11v11 on 2/3 of the pitch, same aims, no zones.', NULL, '10v10 + GK', 21, 22, '2/3 of the pitch', NULL, NULL, NULL, true, true, true, NULL, 350),
  ('Switch to weak-side winger vs full back', 'phase_of_play', 'opposed', 'in_possession', 151, 154, 'Session 11: Practice 1', 'Guardiola (Man City)', 'Switch play to the weak-side winger and create and use a 2v1 against the full back.', 'Final third with GK; on each flank a 12 x 5 yd wide zone split into a yellow (wide) and blue (narrow) half, plus 8 x 7 yd white central zones for the 8s and red full backs; mannequins elsewhere; blue CB, 6, full back, two 8s, wingers and 9 v red full backs.', 'CB to 6, lay-off, CB to dropping full back, who carries and finds the 6; the 6 switches long to the weak-side winger. A: winger receives wide, 8 makes an underlapping run behind the full back and crosses low. B: winger receives narrow, 8 overlaps; if the full back tracks, winger crosses early between defenders and GK. C: 8 sits central, full back pushes up into the white zone and underlaps when winger is wide. D: winger narrow, full back overlaps (or winger crosses early if tracked). Restart on the other side.', NULL, 'Four scenarios A-D by where the winger receives and who supports (8 or full back).', 'Supporting player reads where the winger receives (wide or narrow) and where the nearest CB is; full back uses the flight time of the switch to get forward and make the 2v1.', '10 attackers v 2 full backs + GK', 13, 13, NULL, NULL, NULL, NULL, true, true, true, NULL, 360),
  ('Switch to weak-side winger vs back 4', 'phase_of_play', 'opposed', 'in_possession', 155, 156, 'Session 11: Practice 2', 'Guardiola (Man City)', 'After a switch, read the winger''s position and the nearest centre back to exploit the wide 2v1 in the best way.', 'Final third with GK; two wide zones and a white central zone; mannequins in midfield; same blue pattern as Practice 1 against a full red back 4.', 'Same build-up and long switch by the 6. A: red CB is close enough to cover runs behind the full back, so the 8 stays in support, gets the ball back from the winger and crosses early between defenders and GK. B: CB too far away; 8 sits central, full back pushes into the white zone and underlaps behind the red full back to cross low. Restart on the other side.', NULL, 'Scenario A (CB close) and Scenario B (CB too far away).', 'Read where the winger receives and the nearest CB''s position; full back times his forward run during the ball''s flight.', '10 attackers v 4 defenders + GK', 15, 15, NULL, NULL, NULL, NULL, true, true, true, NULL, 370),
  ('Weak-side switch 10v10 game', 'conditioned_game', 'opposed', 'in_possession', 157, 157, 'Session 11: Practice 3', 'Guardiola (Man City)', 'Switch play and exploit the weak-side overload in a game.', 'About two thirds of the pitch, big goal + GK v two mini goals; wide zones marked; 10 v 10 (+GK), blues start from a centre back on the end line.', 'Blues build and look to switch to the weak side and finish the wide overload; reds counter to the mini goals on regains.', 'Any blue goal 1 point, 2 after switching and exploiting the weak-side overload. Reds 2 points in a mini goal within 10-12 seconds.', '11v11 on 2/3 of the pitch, same aims, no zones.', 'Read where the winger receives and the nearest CB; full back uses ball flight time to arrive and make the 2v1.', '10v10 + GK', 21, 22, '2/3 of the pitch', NULL, NULL, NULL, true, true, true, NULL, 380),
  ('Attacking a back 5, functional', 'phase_of_play', 'opposed', 'in_possession', 172, 174, 'Session 12: Practice 1', 'Guardiola (Man City)', 'Break a 5-4-1 from a 2-2-5-1 by using the wide 2v1s or the centre depending on the defenders'' reactions.', 'Final third with GK; two yellow wide zones (2v1 areas) and a white central zone; 5 mannequins for the red midfield 4 and forward; blues in a 2-2-5-1 v a red back 5.', 'The two blue CBs pass; when one turns, the two midfielders show. A: ball to the advanced full back in the wide zone; wide CB too far to track, so winger runs behind the wing back and crosses. B: CB tracks the winger, full back plays back to the 6 who switches long to the free weak-side winger (or plays into a central gap). C: 6 plays into the central zone; if the CB does not close the 8, he turns and plays a final pass; if he does, a first-time pass to the other free 8 who plays the final ball (9 can also drop to receive).', NULL, 'Scenarios A-C by the defenders'' reaction.', 'Fast 1-2 touch passing; quality low crosses and finishing; synchronised movement; decisions based on defenders'' reactions; receive and turn quickly; combinations to find the free man centrally.', '11 attackers v 5 defenders + GK', 17, 17, NULL, NULL, NULL, NULL, true, true, true, NULL, 390),
  ('Attacking options vs back 5 game', 'conditioned_game', 'opposed', 'in_possession', 175, 175, 'Session 12: Practice 2', 'Guardiola (Man City)', 'Choose between the wide 2v1, a quick switch or the centre against a back 5 in a live game.', 'About two thirds of the pitch, big goal + GK v two mini goals; yellow wide zones and central zone marked; blues start from a centre back on the end line v a red 5-4-1.', 'Blues first try the 2v1 in the wide zones; if reds block it (e.g. wide CB tracks the winger) they switch quickly; if the wide CBs sit wide, they attack through the centre. Reds counter to the mini goals on regains.', 'Reds 2 points in a mini goal within 10-12 seconds. Zones are only a reading aid and can be removed.', NULL, 'Decide by the defenders'' reaction; exploit the wide overload; receive and turn quickly; combine to find the free central player.', '10v10 + GK', 21, 22, '2/3 of the pitch', NULL, NULL, NULL, true, true, true, NULL, 400),
  ('Attacking a back 5, 11v11 game', 'conditioned_game', 'opposed', 'in_possession', 176, 176, 'Session 12: Practice 3', 'Guardiola (Man City)', 'Apply all the solutions against a back 5 in a full conditioned game.', 'Full 11v11 with two big goals and GKs; play starts from the blue GK.', 'Blues build up against a 5-4-1 and look for bonus-goal patterns; normal game otherwise.', 'Any blue goal 1 point; 2 points if from a wide 2v1, a switch when the overload is blocked, or an attack through the centre (turning between the lines or a combination to the free man).', NULL, 'Decide by the defenders'' reaction; exploit the wide overload; receive and turn quickly; combine to find the free central player.', '11v11', 22, 22, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 410)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
CROSS JOIN (SELECT id, source_id FROM coaching_books WHERE slug = 'pep-guardiola-attacking-tactics-tactical-analysis-and-sessions-from-manchester-c') b;
